import hashlib,random
def stable_seed(seed):return int.from_bytes(hashlib.sha256(str(seed).encode()).digest()[:8],'big')
def seed_split(seed):return 'held-out' if stable_seed(seed)%5==0 else 'training'
def generate_hangar(seed):
 r=random.Random(stable_seed(seed));fault=r.choice(['relay','coolant','hydraulic']);exit_name=r.choice(['north_door','roof_gate','service_ramp']);battery=r.randint(4,6);field={'relay':'electrical_ready','coolant':'cooling_ready','hydraulic':'hydraulics_ready'}[fault]
 return {'instance':{'seed':str(seed),'fault':fault,'exit':exit_name},'initial_state':{'access_open':False,'electrical_ready':fault!='relay','cooling_ready':fault!='coolant','hydraulics_ready':fault!='hydraulic','navigation_ready':False,'exit_open':False,'airborne':False,'resources':{'battery':battery}},'sensors':{'visual':{'fields':['access_open','exit_open','airborne']},'diagnostics':{'fields':[field,'navigation_ready'],'available_when':{'access_open':True}}},'actions':{'inspect_access':{'effects':{'access_open':True}},'repair_fault':{'requires':{'access_open':True},'cost':{'battery':1},'effects':{field:True}},'initialize_navigation':{'requires':{'electrical_ready':True,'cooling_ready':True,'hydraulics_ready':True},'cost':{'battery':1},'effects':{'navigation_ready':True}},'open_available_exit':{'requires':{'electrical_ready':True},'cost':{'battery':1},'effects':{'exit_open':True}},'launch':{'requires':{'navigation_ready':True,'exit_open':True},'cost':{'battery':1},'effects':{'airborne':True}}},'success':{'airborne':True}}
